const hc={timer:null,paused:false};
function moverDelta(m){const s=histories.get(m.id),leadId=outcomes(m)[0]?.i,pts=s&&(s.get(leadId)||[...s.values()][0]);if(!pts||pts.length<2)return null;return pts.at(-1).p-pts[0].p;}

function mover(m,i){const l=lead(m),change=moverDelta(m);return `<button class="mover spot" data-pick="${m.id}" data-hc-go="${i}" style="--i:${i}" aria-label="Open ${h(m.marketName)}">${mkImg(m,'spot-media',i<6)}<span class="spot-shade" aria-hidden="true"></span><span class="spot-copy"><b title="${h(m.marketName)}">${h(m.marketName)}</b><span class="spot-foot"><strong class="num">${h(l?.value||'No price')}</strong>${change==null?'':`<small class="${change>=0?'up':'down'}">${change>=0?'+':''}${pct(change)} pts</small>`}${spark(m)}</span></span><span class="spot-details">${legend(m)}<span class="spot-trade">Trade ${hIcon('arrow')}</span></span></button>`;}
function hero(){const top=topFive().slice(0,6);return `<section class="command-deck" id="hc" aria-label="Find a market"><div class="page-heading"><h1>Seer App</h1><p>Find any market, see who is asking and what it prices, and trade it.</p></div><div class="movers-head"><h2>Trending now</h2></div><div class="movers spots" tabindex="0" aria-label="Most traded markets">${top.map(mover).join('')}</div><div class="cmd-block"><div class="command-search"><span class="command-icon">${hIcon('search')}</span><input id="command-search" type="search" value="${h(state.query)}" placeholder="Search a question, market id, asker or outcome" aria-label="Search a question, market id, asker or outcome" autocomplete="off"><kbd aria-hidden="true">/</kbd><button class="command-clear" aria-label="Clear command search"${state.query?'':' hidden'}>${hIcon('close')}</button></div><div class="scope-row" role="group" aria-label="Market type scope">${SCOPES.map(([label,,disabled])=>`<button data-scope="${label}" aria-pressed="${state.scope===label}"${disabled?' disabled aria-disabled="true" title="Not in this record"':''}>${label}</button>`).join('')}</div><p class="command-meta"><b class="num">${state.listMarkets.length}</b> markets</p></div></section>`;}
function wireHero(){const root=$('#hc'),rail=$('.movers',root),input=$('#command-search',root);if(!root||!rail||!input)return;
 const sync=value=>{state.query=value;const nav=$('#search');if(nav&&nav.value!==value)nav.value=value;update();};
 input.oninput=e=>sync(e.target.value);input.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();input.value='';sync('');input.blur();}};
 $('.command-clear',root).onclick=()=>{input.value='';sync('');input.focus();};
 root.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{state.scope=b.dataset.scope;update();$('#hc [data-scope="'+b.dataset.scope+'"]')?.focus();});
 const cards=[...rail.querySelectorAll('.spot')];
 const activate=card=>cards.forEach(c=>c.classList.toggle('is-expanded',c===card));
 let active=0;const CYCLE=7000;const start=()=>{clearInterval(hc.timer);if(reduced()||!root.isConnected)return;hc.paused=false;hc.timer=setInterval(()=>{if(!root.isConnected){clearInterval(hc.timer);return;}active=(active+1)%cards.length;activate(cards[active]);},CYCLE);};
 const stop=()=>{clearInterval(hc.timer);hc.paused=true;};
 cards.forEach(c=>{c.onclick=()=>{stop();location.hash='#/market/'+c.dataset.pick;};c.onpointerenter=e=>{if(e.pointerType==='mouse'){stop();activate(c);active=cards.indexOf(c);}};c.onfocus=()=>{stop();activate(c);active=cards.indexOf(c);};});
 rail.onpointerleave=e=>{if(e.pointerType==='mouse')start();};rail.onfocusout=e=>{if(!rail.contains(e.relatedTarget))start();};
 rail.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();stop();const i=cards.indexOf(document.activeElement),n=e.key==='Home'?0:e.key==='End'?cards.length-1:Math.max(0,Math.min(cards.length-1,i+(e.key==='ArrowRight'?1:-1)));cards[n]?.focus();};
 clearInterval(hc.timer);activate(cards[0]);start();
}

