/* Toolbar */
const viewSeg=()=>`<div class="seg view-seg" role="group" aria-label="View">${[['tiles','Tiles'],['table','Index'],['activity','Activity'],['map','Map']].map(([v,l])=>`<button data-view="${v}" aria-pressed="${state.view===v}">${hIcon({tiles:'grid',table:'table',activity:'activity',map:'map'}[v])}<span>${l}</span></button>`).join('')}</div>`;
function stripIcon(kind){const map={Topic:'grid',State:'activity',Verified:'verified',Chain:'chain',Type:'layers',Advanced:'sliders',Sort:'sort',Clear:'close',Open:'arrow',Copy:'copy',Help:'help',Star:'bookmark'};return hIcon(map[kind]||'help');}
