function market(m){const os=sides(m);if(!os.some(o=>o.i===state.selected))state.selected=os[0]?.i??0;app.innerHTML=`<div class="market-layout"><section class="market-content">${marketHeader(m)}<div class="market-title-row"><h1 class="market-title">${esc(m.marketName)}</h1><div class="market-actions"><button id="market-share" aria-label="Share market">${hIcon('share')}</button><button id="market-star" aria-label="Save market" aria-pressed="${state.saved.has(m.id)}">${hIcon(state.saved.has(m.id)?'star':'bookmark')}</button></div></div><div class="market-meta"><div><small>Liquidity</small><strong>${money(m.liquidityUSD)}</strong></div><div><small>Traded</small><strong>${money(m.volumeUSD)}</strong></div><div><small>Open interest</small><strong>${money(m.openInterestUSD)}</strong></div><div><small>Market type</small><strong>${type(m)}</strong></div></div><div class="information"><p><b>Asked by</b><span><a class="mono" href="${explorer(m)}/address/${m.creator}" target="_blank" rel="noopener noreferrer">${askerLabel(m.creator)} ↗</a> · ${esc(m.verification?.status||'Unverified')}</span></p><p><b>Priced</b><span>${h(ctxPriced(m))}</span></p><p><b>How to read</b><span>${h(ctxHow(m))}</span></p></div><div class="chart-card"><div class="chart-head"><h2>Market signal</h2><button id="export" aria-label="Export current prices">${hIcon('download')} CSV</button></div><div id="winning-chart">${winningChart(m)}</div></div><div class="section-title"><h2>Outcomes <small>${m.outcomes.length}</small></h2><a class="meta" href="https://app.seer.pm/markets/${m.chainId}/${m.url}" target="_blank" rel="noopener noreferrer">Open live market ↗</a></div><div class="market-outcomes">${outcomes(m).map((o,j)=>`<div class="outcome-row"><span>${esc(o.name)}</span><b>${pct(o.p)}%</b><button class="buy ${j===0?'yes':'no'}" data-select="${o.i}" aria-label="Buy ${esc(o.name)}">Buy ${esc(compactName(o.name))}</button><div class="bar"><span class="${j===1?'hatch2':''}" style="width:${pct(Math.min(o.p,100))}%;${j===1?'':'background:'+color(o,j)}"></span></div></div>`).join('')}</div><div class="tabs">${[['Overview','Information'],['Trades / Activity','Activity'],['Resolution','Resolution'],['Related','Related'],['Pools','Pools'],['Price JSON','Price JSON']].map(([label,key])=>`<button data-tab="${key}" class="${state.tab===key?'active':''}">${label}</button>`).join('')}</div><div class="tab-content" id="tab-content"></div><footer class="footer"><a href="#/">${hIcon('back')}All markets</a></footer></section><aside class="trade" aria-label="Order console"><div class="trade-wallet trade-top"><span class="trade-chain">${hIcon('chain')}${chain(m)}</span><span>Order preview</span><button class="trade-close" aria-label="Close order console">${hIcon('close')}</button></div><div class="trade-body" id="trade-body"></div><div class="trade-cta trade-bottom"><p class="tr-err" id="tr-err" role="alert"></p><button class="primary tr-go" id="tr-go">Preview order</button><div class="tr-foot trade-foot">${external("https://app.seer.pm/markets/"+m.chainId+"/"+m.url,"Open on seer.pm ↗",'class="tr-ext"')}</div></div></aside></div><button class="mobile-trade primary" id="mobile-trade">Preview order${hIcon('next')}</button>`;
document.querySelector('[data-topic]')?.addEventListener('click',e=>{state.filters.Topic=e.currentTarget.dataset.topic;});$('.trade-close').onclick=()=>toggleConsole(false);$('#mobile-trade').setAttribute('aria-expanded','false');$('#mobile-trade').onclick=()=>toggleConsole(!$('.trade').classList.contains('open'));$('#export').onclick=()=>exportMarket(m);$('#market-share').onclick=()=>shareMarket(m);$('#market-star').onclick=()=>toggleSaved(m);document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.select);ticket(m);if(innerWidth<1051)toggleConsole(true);});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));tab(m);hSyntax();hSegment();});ticket(m);tab(m);wireChart(m);hSyncPanels();hSyntax();hSegment();if(state.openTrade&&innerWidth<1051)toggleConsole(true);state.openTrade=false;}
function tab(m){let html='';if(state.tab==='Information'||state.tab==='Overview')html=`<div class="detail-list"><div><span>Question opens</span><span>${date(m.openingTs)}</span></div><div><span>Created</span><span>${date(m.blockTimestamp)}</span></div><div><span>Creator</span>${external(explorer(m)+'/address/'+m.creator,askerLabel(m.creator),'class="mono"')}</div><div><span>Verification</span>${external(registry,esc(m.verification?.status))}</div><div><span>Market contract</span><a class="mono" href="${explorer(m)}/address/${m.id}" target="_blank" rel="noopener noreferrer">${short(m.id)} ↗</a></div><div><span>Outcomes</span><span>${esc(m.outcomes.join(' · '))}</span></div></div>`;else if(state.tab==='Activity')html=panelActivity(m);else if(state.tab==='Resolution')html=resolution(m);else if(state.tab==='Pools')html=`<div class="pool-list">${m.poolBalance.filter(Boolean).map(p=>`<div class="pool-row"><span class="pool-label">Pool balances</span><span class="pool-values num">${num(p.token0.balance)} / ${num(p.token1.balance)}</span>${external('https://app.seer.pm/markets/'+m.chainId+'/'+m.url,`View pool details${hIcon('arrow')}`,'class="pool-action"')}</div>`).join('')}</div>`;else if(state.tab==='Related')html=`<div class="related-list">${state.markets.filter(x=>x.id!==m.id&&x.creator===m.creator).slice(0,12).map(x=>`<a href="#/market/${x.id}"><span>${esc(x.marketName)}</span>${hIcon('arrow')}</a>`).join('')}</div>`;else html=`<pre class="price-code">${esc(JSON.stringify(signal(m),null,2))}</pre><button id="copy-signal" class="soft">Copy JSON</button>`;$('#tab-content').innerHTML=html;$('#copy-signal')?.addEventListener('click',()=>copy(JSON.stringify(signal(m),null,2)));}
function signal(m){return {market:m.id,question:m.marketName,chainId:m.chainId,creator:m.creator,outcomes:outcomes(m),liquidityUSD:m.liquidityUSD,volumeUSD:m.volumeUSD,verification:m.verification?.status};}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Copied JSON');}catch{modal('Signal JSON',`<textarea style="width:100%;height:240px">${esc(s)}</textarea>`);}}
/* Full market page order console: live balance scale, plain-text Pay/Get, in-app trade */
const SCALE_MAX=1000;
function ticket(m){state.tOut=state.selected;const root=$('#trade-body');const actions=$('.trade-bottom');actions?.remove();root.innerHTML=unifiedTicket(m,true)+`<details class="tr-more"><summary>Details and actions</summary><label>Max slippage<select id="slippage">${[.5,1,2,5].map(n=>`<option>${n}%</option>`).join('')}</select></label><div class="tr-actions">${['Mint','Merge','Redeem'].map(v=>`<button data-action="${v}" class="soft">${v}</button>`).join('')}</div></details>`;if(actions)$('.unified-ticket',root).append(actions);wireUnified(root,m,true);root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>modal(b.dataset.action,`<p>${h(m.marketName)}</p>${external('https://app.seer.pm/markets/'+m.chainId+'/'+m.url,b.dataset.action+' on seer.pm')}`));hSyncPanels();hSyntax(root);hSegment();}

function render(){document.body.classList.remove('console-open');closeMenu(false);closeSheet();const r=route();document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===(r==='#/leaderboard'?'leaderboard':(isHome()||r.startsWith('#/market/'))?'markets':'');a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});app.classList.remove('route-enter');void app.offsetWidth;app.classList.add('route-enter');if(r==='#/leaderboard'){leaderboard();return;}if(r==='#/create'){create();return;}if(r==='#/policies'){policies();return;}if(r.startsWith('#/market/')){const id=decodeURIComponent(r.replace('#/market/',''));const m=state.markets.find(m=>m.id===id);if(m)market(m);else app.innerHTML='<div class="empty">Market not found <a href="#/">All markets →</a></div>';return;}readQuery();home();}
document.addEventListener('keydown',e=>{if(!location.hash.startsWith('#/market/')||!/ArrowUp|ArrowDown/.test(e.key)||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||!pop.hidden||dialog.open)return;e.preventDefault();const list=filtered();const i=list.findIndex(m=>location.hash.endsWith(m.id));const m=list[(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length];if(m)location.hash='#/market/'+m.id;});
window.addEventListener('hashchange',()=>{state.tab='Information';render();if(!isHome())window.scrollTo(0,0);});
try{document.documentElement.dataset.theme=localStorage.getItem('seer.theme')||localStorage.getItem('seer-theme')||localStorage.getItem('deck.theme')||'dark';}catch{document.documentElement.dataset.theme='dark';}
window.addEventListener('seer:theme',e=>{const t=e.detail&&e.detail.theme==='light'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('seer.theme',t);localStorage.setItem('deck.theme',t);}catch(_){}if(isHome()&&$('#ix-body')){update();}});

fetch('./data/markets.json').then(r=>{if(!r.ok)throw Error('data');return r.json();}).then(data=>{prepareMarkets(data);normalizeLegacyRoute();return loadHistory().then(()=>{header();render();});}).catch(e=>{console.warn(e);app.innerHTML='<div class="empty">Could not load markets. <button onclick="location.reload()">Retry</button></div>';});
addEventListener('resize',()=>{const p=$('#ix-panel');if(!p)return;if(desktop()){p.inert=false;p.classList.remove('open');$('#ix-scrim').hidden=true;document.body.classList.remove('sheet-open');}else if(!p.classList.contains('open'))p.inert=true;});

function policies(){app.innerHTML=`<section class="create-view policies-view"><a class="meta" href="#/">← Markets</a><div class="create-heading"><h1>Market policies</h1></div><h2 id="verified-market">Verified Market policy</h2><p class="policy-text">A market is marked Verified when its question, outcomes and resolution source are clear, and it follows the Market Rules. Unverified markets can still be read here, but the question may be vague or the source weak. Check the mark before relying on a price.</p><h2 id="market-rules">Market Rules</h2><ul class="policy-list"><li>The question must have one clear answer by a stated date.</li><li>Outcomes must not overlap, and a market that cannot be resolved is settled as Invalid.</li><li>The resolution source must be public and checkable.</li><li>Markets that promote harm, or that can be settled by their creator alone, are not accepted.</li></ul><p class="wallet-note">Full policy text lives on Seer.</p><div class="create-bottom"><a href="#/">Back to markets</a>${policyLinks().split('</a>').slice(1).join('</a>')}</div></section>`;}
let createStep=1;
function create(){createStep=1;drawCreate();}
function drawCreate(){const two=createStep===2;const types=['Categorical','Multi categorical','Scalar','Multi scalar'];const desc={Categorical:'One outcome wins','Multi categorical':'Multiple outcomes may win',Scalar:'A numeric result within a range','Multi scalar':'Numeric results across several outcomes'};
const body=two?`<fieldset disabled class="create-preview"><legend>${esc(state.createType||'Categorical')} market (preview)</legend><label class="field">Question<input type="text" placeholder="Will ... happen by ...?" disabled></label><label class="field">Outcomes<input type="text" placeholder="Yes, No" disabled></label><div class="field-row"><label class="field">Opening date<input type="text" placeholder="YYYY-MM-DD" disabled></label><label class="field">Closing date<input type="text" placeholder="YYYY-MM-DD" disabled></label></div><label class="field">Resolution source<input type="text" placeholder="https://" disabled></label></fieldset><div class="wallet-note">Creating markets happens on Seer</div>`:`<fieldset><legend>Type</legend>${types.map(t=>`<label class="type-choice"><input type="radio" name="market-type" value="${t}"${state.createType===t?' checked':''}><span><b>${t}</b><small>${esc(desc[t])}</small></span></label>`).join('')}</fieldset><div class="wallet-note">Choose a type, then Next shows what a market needs.</div>`;
app.innerHTML=`<section class="create-view"><a class="meta" href="#/">← Markets</a><div class="create-heading"><h1>Create market</h1><p class="step-caption">Step ${createStep} of 2</p><div class="create-steps" aria-label="Step ${createStep} of 2"><span class="current"></span><span${two?' class="current"':''}></span></div></div>${body}<div class="create-bottom">${two?'<button id="create-back" class="link">Back</button>':'<a href="#/">Cancel</a>'}<button class="primary" id="create-next"${!two&&!state.createType?' disabled title="Choose a market type"':''}>${two?'Open on Seer':'Next'}</button></div></section>`;
document.querySelectorAll('[name="market-type"]').forEach(n=>n.onchange=()=>{state.createType=n.value;$('#create-next').disabled=false;$('#create-next').title='';});
$('#create-next').onclick=()=>{if(!two){createStep=2;drawCreate();$('#create-next').focus();}else openOnSeer();};
if(two)$('#create-back').onclick=()=>{createStep=1;drawCreate();};}
function openOnSeer(){modal('Open on Seer','<p>Creating markets happens on Seer, where you connect your wallet on Gnosis and fill in the question, outcomes, dates and resolution source.</p><a href="https://app.seer.pm" target="_blank" rel="noopener noreferrer">Open on Seer ↗</a>');}

const histories=new Map();
async function loadHistory(){await Promise.all(['market-chart','markets-charts'].map(async name=>{try{const response=await fetch('./data/'+name+'.json');if(!response.ok)return;const fixture=await response.json();const raw=fixture.data?._raw_truncated;if(!raw)return;const endpointId=fixture._endpoint.match(/marketId=(0x[0-9a-f]+)/i)?.[1];
// Recover only complete JSON observations. The unfinished final object is ignored.
for(const match of raw.matchAll(/\{"pool":\{.*?"periodStartUnix":\d+\}/g)){let row;try{row=JSON.parse(match[0]);}catch{continue;}const market=state.markets.find(m=>(!endpointId||m.id===endpointId)&&m.wrappedTokens?.some(t=>[row.pool.token0.id,row.pool.token1.id].includes(t)));if(!market)continue;const index=market.wrappedTokens.findIndex(t=>t===row.pool.token0.id||t===row.pool.token1.id);const outcomeIs0=market.wrappedTokens[index]===row.pool.token0.id;const price=Number(outcomeIs0?row.token1Price:row.token0Price)*100;if(!Number.isFinite(price)||price<0||price>100)continue;let series=histories.get(market.id);if(!series){series=new Map();histories.set(market.id,series);}if(!series.has(index))series.set(index,[]);series.get(index).push({t:Number(row.periodStartUnix),p:price});}
}catch{/* Missing history leaves the honest record visible. */}}));histories.forEach(series=>series.forEach((points,key)=>series.set(key,points.map(p=>({t:Number(p.t),p:Number(p.p)})).filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.p)).sort((a,b)=>a.t-b.t))));}

function marketHeader(m){const opening=Number(m.openingTs),st=status(m);const label=st==='Reports open'?'Open':st==='Reports not open yet'?'Trading open':st;return `<header class="market-heading"><div class="market-nav-row"><a class="back-markets soft" href="#/">${hIcon('back')}Back to markets</a><nav class="breadcrumb" aria-label="Breadcrumb"><a href="#/">Markets</a><span>/</span><a href="#/?topic=${encodeURIComponent(m.categories[0]||'misc')}" data-topic="${esc(m.categories[0]||'misc')}">${esc(m.categories[0]||'misc')}</a><span>/</span><span class="crumb-title" title="${esc(m.marketName)}">${esc(m.marketName.split(' ').slice(0,7).join(' '))}</span></nav></div><div class="status-cluster"><span title="Market status and reporting date" class="status-pill label-shape" data-status="${esc(st)}"><i></i>${esc(label)} · ${opening>NOW?'reports '+date(opening):'since '+date(opening)}</span>${badge(m)}${external(explorer(m)+'/address/'+m.id,hIcon('chain')+esc(chain(m)),'class="chain-chip label-shape" title="Chain explorer contract"')}<span title="Market type" class="type-chip label-shape">${type(m)}</span>${conditional(m)?`<a class="conditional label-shape" href="#/market/${m.parentMarket.id}" target="_blank" rel="noopener noreferrer" title="Conditional parent market">Conditional ${hIcon('arrow')}</a>`:''}${external(realityUrl(m),'Reality.eth '+hIcon('arrow'),'class="reality-link label-shape"')}</div></header>`;}

// Prices are independent pool observations, never normalized or inferred.
function chartData(m){
 const series=histories.get(m.id);if(!series)return null;
 const all=[...series.values()].flat();if(!all.length)return null;
 const end=Math.max(...all.map(p=>p.t));
 const start=state.range==='All'?Math.min(...all.map(p=>p.t)):end-({'1D':86400,'1W':604800,'1M':2592000}[state.range]||0);
 const groups=outcomes(m).filter(o=>series.has(o.i)).slice(0,3).map((o,j)=>({...o,j,c:color(o,j),points:series.get(o.i).filter(p=>p.t>=start&&p.t<=end)}));
 return {start,end,groups};
}
function chanceDial(m){return `<div class="probability-signal"><strong class="num">${pct(outcomes(m)[0]?.p||0)}<small>%</small></strong><p>${h(ctxHow(m))}</p>${outcomes(m).slice(0,4).map(o=>`<div class="prob-row" tabindex="0" aria-label="${h(o.name)} ${pct(o.p)} percent"><span>${h(o.name)}</span><b>${pct(o.p)}%</b><i><i style="transform:scaleX(${clamp(o.p)/100})"></i></i></div>`).join('')}</div>`;}

function payoffStrip(m){
 const os=sides(m),selected=os.find(o=>o.i===state.selected)||os[0];if(!selected)return '';
 const payout=selected.p>0?1000/selected.p:0;
 return `<section class="payoff instrument-enter" style="--step:1"><h3>If you put in 10</h3><p class="meta">Buy ${esc(selected.name)} at ${num(selected.p)} · Before fees</p><div class="payoff-bars">${[selected,...os.filter(o=>o.i!==selected.i)].slice(0,3).map((o,j)=>{const value=o.i===selected.i?payout:0;return `<div class="o${Math.min(j,2)+1}" style="--outcome-color:${color(o,j)}"><span>${scalar(m)?(/^up$/i.test(o.name)?'At upper bound':'At lower bound'):'If '+esc(o.name)+' wins'}: you get</span><strong>${num(value)}</strong><div class="payoff-track"><i style="width:${pct(value?100:0)}%"></i></div></div>`;}).join('')}</div>${scalar(m)?'<p class="meta">Scalar settlement pays proportionally within the range.</p>':''}</section>`;
}
function runway(m){
 const opened=Number(m.blockTimestamp),reports=Number(m.openingTs),end=Math.max(opened,NOW,reports),fraction=Math.max(0,Math.min(1,(NOW-opened)/Math.max(1,end-opened))),days=Math.ceil((reports-NOW)/86400);
 const events=[{label:'Opened',time:opened},{label:'Reports open',time:reports},{label:'Now',time:NOW}].sort((a,b)=>a.time-b.time);
 return `<section class="runway instrument-enter" style="--step:2"><h3>Runway <small>${days>0?days+' days until reports open':'Reports opened '+date(reports)}</small></h3><div class="runway-track" role="img" aria-label="Opened ${date(opened)}. Reports open ${date(reports)}. Record now ${date(NOW)}."><i style="--progress:${pct(fraction*100)}%"></i><b class="report-tick" style="left:${pct(Math.max(0,Math.min(100,(reports-opened)/Math.max(1,end-opened)*100)))}%" title="Reports open: ${date(reports)}"></b></div><div class="runway-dates">${events.map(e=>`<span>${e.label}<b>${date(e.time)}</b></span>`).join('')}</div><p class="meta">Resolution follows reporting · Final date not fixed</p></section>`;
}
function historyVisual(m){
 const data=chartData(m);if(!data)return `<div class="history-empty">${hIcon('history')}<div><b>No recorded history</b><p>History not recorded for this market. The current record is shown above.</p></div></div>`;
 const W=620,H=212,L=42,R=74,T=24,B=36,x=t=>L+(t-data.start)/Math.max(1,data.end-data.start)*(W-L-R),y=p=>H-B-p/100*(H-T-B);
 const groups=data.groups.map(g=>{const pts=g.points,xy=pts.map(p=>[x(p.t),y(p.p)]),line=smoothPath(xy);return `<g data-series="${g.j}">${pts.length>1?`${g.j===0?`<path d="${line}L${x(pts.at(-1).t)} ${H-B}L${x(pts[0].t)} ${H-B}Z" fill="url(#history-fill)"/>`:''}<path d="${line}" class="history-line" fill="none" stroke="${g.c}" stroke-width="${g.j===0?2.5:1.6}"${g.j===1?' stroke-dasharray="5 4"':''}/>`:''}${pts.map((p,i)=>`<circle tabindex="0" role="img" aria-label="${h(g.name)} ${pct(p.p)} percent on ${date(p.t)}" cx="${x(p.t)}" cy="${y(p.p)}" r="${i===pts.length-1?3.5:1.8}" fill="${g.c}"><title>${h(g.name)} ${pct(p.p)}% · ${date(p.t)}</title></circle>`).join('')}${pts.length?`<text x="${W-R+10}" y="${Math.max(T+12,Math.min(H-B-6,y(pts.at(-1).p)-8))}" fill="${g.c}" font-size="12">${h(compactName(g.name))} ${pct(pts.at(-1).p)}%</text>`:''}</g>`;}).join('');
 const tableRows=[...new Map(data.groups.flatMap(g=>g.points.map(p=>[p.t,{t:p.t}]))).values()].sort((a,b)=>a.t-b.t).map(r=>`<tr><td>${date(r.t)}</td>${data.groups.map(g=>{const p=g.points.find(p=>p.t===r.t);return `<td class="num">${p?pct(p.p)+'%':'n/a'}</td>`;}).join('')}</tr>`).join('');
 return `<section class="history-panel"><div class="chart-head"><h3>How the odds moved</h3><div class="ranges">${['1D','1W','1M','All'].map(r=>`<button data-range="${r}" aria-pressed="${state.range===r}" class="${state.range===r?'active':''}">${r}</button>`).join('')}</div></div><div class="history-canvas" tabindex="0" role="group" aria-label="Recorded odds. Use left and right arrows to read observations."><svg class="history-ridge" viewBox="0 0 ${W} ${H}" aria-label="Recorded odds, zero to one hundred percent"><defs><linearGradient id="history-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--lilac)" stop-opacity=".22"/><stop offset="1" stop-color="var(--lilac)" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(p=>`<path d="M${L} ${y(p)}H${W-R}" stroke="var(--line)"/><text x="${L-9}" y="${y(p)+4}" text-anchor="end" fill="var(--text-2)" font-size="12">${p}%</text>`).join('')}${groups}<g class="history-crosshair" hidden><path class="crosshair-line" y1="${T}"/><circle r="4"/><rect width="192" height="40" rx="6"/><text></text></g><text x="${L}" y="${H-8}" fill="var(--text-2)" font-size="12">${date(data.start)}</text><text x="${W-R}" y="${H-8}" text-anchor="end" fill="var(--text-2)" font-size="12">${date(data.end)}</text></svg></div><div class="history-labels">${data.groups.map(g=>`<span style="--outcome-color:${g.c}"><i></i>${h(g.name)} <b>${g.points.length?pct(g.points.at(-1).p)+'%':'No observations in window'}</b></span>`).join('')}</div><p class="meta">Captured pool observations · Actual timestamps · No interpolation</p><details class="chart-table"><summary>Price data table</summary><div><table><thead><tr><th>Date</th>${data.groups.map(g=>`<th>${h(g.name)}</th>`).join('')}</tr></thead><tbody>${tableRows}</tbody></table></div></details></section>`;
}
function winningChart(m){return `<div class="instrument-enter">${chanceDial(m)}</div><div id="payoff-strip">${payoffStrip(m)}</div>${runway(m)}<div id="history-panel" class="instrument-enter" style="--step:3">${historyVisual(m)}</div>`;}
function animateInstrument(root){if(!root||reduced())return;for(const el of root.querySelectorAll('.chance-needle'))el.animate([{transform:'rotate(0deg)'},{transform:`rotate(${el.style.getPropertyValue('--needle-angle')})`}],{duration:600,easing:'cubic-bezier(.16,1,.3,1)'});}
function wireChart(m){wireHistory(m);animateInstrument($('#winning-chart'));}
function wireHistory(m){document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{state.range=b.dataset.range;$('#history-panel').innerHTML=historyVisual(m);wireHistory(m);});hHistoryCrosshair(m);hSegment($('#history-panel'));}
/* Balance scale: beam angle springs toward a target set by position size (amount / SCALE_MAX) and the pay vs get ratio.
   The heavier Get pan sits on the side of the chosen outcome button, so switching Yes/No flips the tilt. */
const sc={x:0,v:0,t:0,raf:0,getLeft:true,oc:0,nL:0,nR:0};
const BEAM=112;
function scaleSvg(getLeft,oc){const pan=(id,get)=>`<g id="${id}" class="sc-pan${get?' get':''}"><path class="sc-str" d="M0 0 -30 57M0 0 30 57"/><circle class="sc-hook" r="2"/><g class="sc-coins" id="${id}-c"></g><path class="sc-dish" d="M-36 57h72c-4 11-17 17-36 17S-32 68-36 57Z"/><path class="pan-rim" d="M-36 57h72"/></g>`;return `<div class="sc-wrap o${oc+1}"><svg class="sc" viewBox="0 0 320 156" role="img" aria-label="Balance scale: what you pay against what you get"><ellipse class="sc-shadow" cx="160" cy="145" rx="88" ry="3"/><path class="sc-post" d="M157 41h6l5 94h-16Z"/><path class="post-edge" d="M160 47v82"/><rect class="sc-foot" x="128" y="135" width="64" height="6" rx="3"/>${pan('sc-l',getLeft)}${pan('sc-r',!getLeft)}<g id="sc-beam"><path class="sc-beam" d="M${160-BEAM} 34H${160+BEAM}"/><path class="beam-edge" d="M${160-BEAM} 32H${160+BEAM}"/><circle class="sc-end" cx="${160-BEAM}" cy="34" r="3"/><circle class="sc-end" cx="${160+BEAM}" cy="34" r="3"/></g><circle class="sc-pivot" cx="160" cy="34" r="7"/><circle class="sc-pin" cx="160" cy="34" r="2.5"/></svg></div>`;}
function coins(n,prev,get){return Array.from({length:n},(_,i)=>{const y=52-i*4.5;return `<g class="cn${i>=prev?' cn-new':''}"><ellipse cx="0" cy="${y+3}" rx="18" ry="4" class="cn-side"/><path d="M-18 ${y}v3a18 4 0 0 0 36 0v-3" class="cn-side"/><ellipse cx="0" cy="${y}" rx="18" ry="4" class="cn-top${get?' cn-get':''}"/><path d="M-13 ${y}a13 2 0 0 0 26 0" class="coin-etch"/></g>`;}).join('');}
function placeScale(){const bm=$('#sc-beam');if(!bm)return;const a=sc.x*Math.PI/180,cx=BEAM*Math.cos(a),cy=BEAM*Math.sin(a);bm.setAttribute('transform',`rotate(${sc.x.toFixed(3)} 160 34)`);$('#sc-l').setAttribute('transform',`translate(${(160-cx).toFixed(2)} ${(34-cy).toFixed(2)})`);$('#sc-r').setAttribute('transform',`translate(${(160+cx).toFixed(2)} ${(34+cy).toFixed(2)})`);}
function scaleTo(pay,get){const size=Math.min(1,pay/SCALE_MAX),ratio=pay>0?(get-pay)/(get+pay):0,mag=pay>0?Math.min(16,(.15+.85*Math.sqrt(size))*(5+11*Math.max(0,ratio))):0;
 const n=v=>v>0?Math.max(1,Math.min(10,1+Math.round(v/SCALE_MAX*8))):0,nPay=n(pay),nGet=n(get);
 const L=sc.getLeft?nGet:nPay,R=sc.getLeft?nPay:nGet,lc=$('#sc-l-c'),rc=$('#sc-r-c');
 if(lc&&rc){const fresh=!lc.childElementCount&&!rc.childElementCount;lc.innerHTML=coins(L,fresh?L:sc.nL,sc.getLeft);rc.innerHTML=coins(R,fresh?R:sc.nR,!sc.getLeft);sc.nL=L;sc.nR=R;}
 sc.t=(sc.getLeft?-1:1)*mag;
 if(reduced()){cancelAnimationFrame(sc.raf);sc.raf=0;sc.x=sc.t;sc.v=0;placeScale();return;}
 if(sc.raf)return;let last=performance.now();
 const step=now=>{const dt=Math.min(.032,(now-last)/1000);last=now;const acc=-260*(sc.x-sc.t)-20*sc.v;sc.v+=acc*dt;sc.x+=sc.v*dt;
  if(Math.abs(sc.v)<.02&&Math.abs(sc.x-sc.t)<.02){sc.x=sc.t;sc.v=0;sc.raf=0;placeScale();return;}placeScale();sc.raf=requestAnimationFrame(step);};
 sc.raf=requestAnimationFrame(step);}
/* Quotes are plain text: every glyph stays in the natural line box. */
function rollTo(el,text){if(!el)return;el.dataset.v=String(text);el.textContent=String(text);el.removeAttribute('role');el.removeAttribute('aria-label');}

/* In-app trade flow, shared by the list panel and the full market page: wallet state, validation, confirm sheet, success */
const wallet={addr:(()=>{try{return sessionStorage.getItem('seer.wallet')||'';}catch{return '';}})(),balance:2500};
const MIN_AMT=1,MAX_AMT=10000,SLIP=0.5,FEE=0.002;
function connected(){const s=window.seerShell;if(s&&typeof s.isConnected==='function')return !!s.isConnected();if(s&&typeof s.address==='string')return !!s.address;return !!wallet.addr;}
function connect(){window.dispatchEvent(new CustomEvent('seer:connect',{cancelable:true}));const s=window.seerShell;if(s&&typeof s.openConnect==='function'){s.openConnect();return;}window.dispatchEvent(new CustomEvent('seer:connect',{cancelable:true}));setTimeout(()=>{if(document.querySelector('.sg-modal-wrap'))return;[...document.querySelectorAll('body > header button, .sg button')].find(b=>/connect/i.test(b.textContent))?.click();},60);}
function walletChanged(){if(isHome())panel();else if(route().startsWith('#/market/')){const m=state.q?.m;if(m)ticket(m);else setCta();}}
window.addEventListener('seer:wallet',e=>{wallet.addr=e.detail?.address||'connected';walletChanged();});
window.addEventListener('seer:disconnect',()=>{wallet.addr='';walletChanged();});
function amountError(a){if(!(a>0))return 'Enter an amount to pay';if(a<MIN_AMT)return `Minimum order is ${MIN_AMT}`;if(a>MAX_AMT)return `Maximum order is ${num(MAX_AMT)}`;if(a>wallet.balance)return `Exceeds demo balance of ${num(wallet.balance)}`;return '';}
function legacySetCta(){const b=$('#tr-go');if(!b)return;const q=state.q,on=connected(),err=q?amountError(q.pay):'';b.textContent=`Preview buy ${q?.name||''}`;b.classList.toggle('o2',on&&sc.oc===1);const e=$('#tr-err');if(e)e.textContent=err;$('#amount')?.setAttribute('aria-invalid',String(!!err));const bal=$('#amt-bal');if(bal)bal.textContent=`Demo balance ${num(wallet.balance)}`;}
function txHash(){const b=new Uint8Array(32);crypto.getRandomValues(b);return '0x'+[...b].map(x=>x.toString(16).padStart(2,'0')).join('');}
function confirmTrade(q){const rows=q.sell?[['You sell',num(q.pay)+' shares'],['You receive, about',num(q.get)],['Avg price',q.avg.toFixed(2)]]:[['You pay',num(q.pay)],[scalar(q.m)?`Get at ${/^up$/i.test(q.name)?'upper':'lower'} bound`:`You get if ${q.name} wins`,num(q.get)+' shares'],['Avg price',q.avg.toFixed(2)]];rows.push(['Max slippage',SLIP+'%'],['Fees, est.',num(q.pay*FEE)]);
 modal(`Simulate: ${q.sell?'Sell':'Buy'} ${q.name}`,`${tradeHead(q.m)}<p class="demo-notice">Simulated order, no funds move</p><p class="cf-q">${esc(q.m.marketName)}</p><dl class="cf-dl">${rows.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd class="num">${b}</dd></div>`).join('')}</dl><div class="cf-act"><button class="soft" id="cf-cancel">Cancel</button><button class="primary" id="cf-ok">Simulate order</button></div>`);
 dialog.querySelectorAll('[data-ticket-back]').forEach(b=>b.onclick=backMarkets);dialog.classList.add('cf');$('#cf-cancel').onclick=()=>dialog.close();
 $('#cf-ok').onclick=()=>{const b=$('#cf-ok');b.disabled=true;b.textContent='Simulating';setTimeout(()=>tradeDone(q),reduced()?0:700);};$('#cf-ok').focus();}
function tradeDone(q){if(!dialog.open)return;dialog.setAttribute('aria-label','Simulation complete');const hash=txHash();wallet.balance=Math.max(0,wallet.balance+(q.sell?q.get:-q.pay));
 dialog.innerHTML=`<button class="close" aria-label="Close dialog">×</button><span class="cf-mark" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5 9-10"/></svg></span><h2>Simulation complete</h2><p class="demo-notice">Demo values only. No transaction was sent. Wallet signing is rejected in this demo.</p><p class="cf-q">${q.sell?`Simulated selling ${num(q.pay)} ${esc(q.name)} shares for about ${num(q.get)}.`:`Demo position: ${num(q.get)} ${esc(q.name)} shares. ${scalar(q.m)?`They pay up to ${num(q.get)} at the ${/^up$/i.test(q.name)?'upper':'lower'} bound and settle proportionally within the range.`:`They pay ${num(q.get)} if ${esc(q.name)} wins.`}`}</p><dl class="cf-dl"><div><dt>Simulation ID</dt><dd class="mono" title="${hash}">${short(hash)}</dd></div><div><dt>Demo position</dt><dd class="num">${num(q.sell?0:q.get)} ${esc(q.name)}</dd></div><div><dt>Demo balance</dt><dd class="num">${num(wallet.balance)}</dd></div></dl><div class="cf-act"><button class="soft" id="cf-done">Done</button><a class="primary" id="cf-view" href="#/market/${q.m.id}">View market</a></div>`;
 $('.close',dialog).onclick=()=>dialog.close();$('#cf-done').onclick=()=>dialog.close();$('#cf-view').onclick=()=>dialog.close();$('#cf-view').focus();walletChanged();}
dialog.addEventListener('close',()=>dialog.classList.remove('cf'));

const leaders={data:null,period:'All',app:'All',chain:'All',search:'',sort:'pnl',desc:true,page:0};
async function leaderboard(){closeMenu(false);if(!leaders.data){app.innerHTML='<div class="loading">Loading leaderboard…</div>';try{const r=await fetch('./data/get-pnl-leaderboard.json');if(!r.ok)throw Error('leaderboard');leaders.data=(await r.json()).data;}catch{app.innerHTML='<div class="empty">Could not load leaderboard. <button id="retry-leaders">Retry</button></div>';$('#retry-leaders').onclick=leaderboard;return;}if(location.hash!=='#/leaderboard')return;}
const d=leaders.data;const top=[...d.rows].sort((a,b)=>b.pnl-a.pnl)[0];
app.innerHTML=`<section class="leaderboard"><div class="leader-heading"><div><a href="#/" class="meta">Markets /</a><h1>Leaderboard</h1><p class="meta">Trader performance · ${new Date(d.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</p></div><button class="soft" id="your-rank">Your rank</button></div><div class="leader-controls"><div class="period-tabs" aria-label="Leaderboard period">${['1D','1W','1M','All'].map(p=>p==='All'?`<button data-period="All" aria-pressed="true">All time</button>`:`<span class="lp-wrap"><button aria-disabled="true" data-period-na="${p}" aria-describedby="lp-why" aria-pressed="false">${p}</button></span>`).join('')}<span class="lp-tip" id="lp-why" role="tooltip">Seer's leaderboard feed returns all-time totals only, with no per-trade timestamps, so 1D, 1W and 1M rankings cannot be derived.</span></div><button class="sentence-trigger" data-leader-filter="app" aria-expanded="false">App: ${esc(leaders.app)} ⌄</button><button class="sentence-trigger" data-leader-filter="chain" aria-expanded="false">Chain: ${esc(leaders.chain)} ⌄</button></div><p class="meta" role="status" id="leader-status"></p>${leaderVisuals(d.rows)}<div class="leader-search-row"><input type="search" id="leader-search" placeholder="Search address or username" aria-label="Search address or username" value="${esc(leaders.search)}"></div><div id="leader-table-area"></div><details class="score-explainer"><summary>How the Trader Score works</summary><p>Scores combine returns, profit factor, hit rate, loss burn and market breadth. Small samples are reduced toward the baseline. At least three scored markets are required.</p><div class="score-components">${Object.entries(top.scoreBreakdown.components).map(([k,v])=>`<span>${esc(k)} <b>${num(v)}</b></span>`).join('')}</div><small>Component values for rank 1 · Score ${top.score}</small></details><footer class="footer"><span>25 accounts of 4,130</span><a href="https://app.seer.pm/leaderboard" target="_blank" rel="noopener noreferrer">Full live leaderboard ↗</a></footer></section>`;
{const pr=[...d.rows].sort((a,b)=>b.pnl-a.pnl).slice(0,3),ord=[1,0,2],shortA=a=>a.slice(0,6)+'…'+a.slice(-4),hue=a=>(parseInt(a.slice(2,8),16)%60)+250;$('.leader-controls').insertAdjacentHTML('beforebegin',`<section class="podium" aria-label="Top three traders">${ord.map(k=>{const r=pr[k];if(!r)return '';return `<article class="pod pod-${k+1}" style="--h:${hue(r.address)};--i:${k}"><span class="pod-rank num">${k+1}</span><span class="pod-av" aria-hidden="true">${r.address.slice(2,4).toUpperCase()}</span><b class="pod-name mono">${shortA(r.address)}</b><strong class="pod-pnl num">${r.pnl>=0?'+':''}$${Math.round(r.pnl).toLocaleString('en-US')}</strong><span class="pod-meta"><span>Volume <b class="num">$${Math.round(r.volume).toLocaleString('en-US')}</b></span><span>ROI <b class="num">${(r.roi*100).toFixed(1)}%</b></span><span>${r.marketCount} market${r.marketCount==1?'':'s'}</span></span><span class="pod-tier">${esc(r.tier||'')} · ${Math.round(r.score)}</span></article>`}).join('')}</section>`);}
leaderTable();
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{leaders.period=b.dataset.period;leaders.page=0;leaderboard();});document.querySelectorAll('[data-period-na]').forEach(b=>b.onclick=()=>toast(`${b.dataset.periodNa} ranking unavailable: the feed has all-time totals only`));document.querySelectorAll('[data-leader-filter]').forEach(b=>hoverMenu(b,()=>{const key=b.dataset.leaderFilter;const options=key==='app'?['All','Seer','Futarchy','Deepfunding','Foresight']:['All','Gnosis','Ethereum','OP Mainnet','Base'];menu(b,`<div class="menu-title">${key==='app'?'Application':'Chain'}</div>${options.map(v=>`<button data-leader-option="${v}" aria-pressed="${leaders[key]===v}">${v}<span>${leaders[key]===v?'✓':''}</span></button>`).join('')}`);pop.querySelectorAll('[data-leader-option]').forEach(o=>o.onclick=()=>{leaders[key]=o.dataset.leaderOption;leaders.page=0;closeMenu();leaderboard();document.querySelector('[data-leader-filter='+key+']')?.focus();});}));$('#leader-search').oninput=e=>{leaders.search=e.target.value;leaders.page=0;leaderTable();};$('#your-rank').onclick=()=>{modal('Your rank','<p>Search the captured leaderboard by wallet address.</p><form id="rank-form"><label for="rank-address">Wallet address</label><input id="rank-address" required placeholder="0x…" style="width:100%;margin:16px 0"><button class="primary">Find rank</button></form>');$('#rank-form').onsubmit=e=>{e.preventDefault();leaders.search=$('#rank-address').value.trim();leaders.period=leaders.app=leaders.chain='All';leaders.page=0;dialog.close();leaderboard();};};}

function leaderTable(){const d=leaders.data,available=leaders.period==='All'&&leaders.app==='All'&&leaders.chain==='All';let rows=available?d.rows.filter(r=>((r.username||'')+' '+r.address).toLowerCase().includes(leaders.search.trim().toLowerCase())):[];rows.sort((a,b)=>((a[leaders.sort]??-Infinity)-(b[leaders.sort]??-Infinity))*(leaders.desc?-1:1));const pages=Math.max(1,Math.ceil(rows.length/10));leaders.page=Math.min(leaders.page,pages-1);
$('#leader-status').textContent=available?`${rows.length} accounts of ${num(d.total)} total · All-time · All apps · All chains`:`${leaders.period} · ${leaders.app} apps · ${leaders.chain} chains: no data is available for these filters.`;
$('#leader-table-area').innerHTML=`<div class="leader-table-wrap"><table class="leader-table"><thead><tr>${[['rank','Rank'],['address','Account'],['score','Trader Score'],['pnl','Profit / loss'],['volume','Volume'],['roi','ROI'],['marketCount','Markets']].map(([k,label])=>`<th scope="col" ${leaders.sort===k?`aria-sort="${leaders.desc?'descending':'ascending'}"`:''}>${k==='address'?label:`<button data-leader-sort="${k}">${label}${leaders.sort===k?(leaders.desc?' ↓':' ↑'):''}</button>`}</th>`).join('')}</tr></thead><tbody>${rows.slice(leaders.page*10,leaders.page*10+10).map((r,i)=>`<tr style="--row:${i}"><td>${r.rank}</td><td><a class="account-cell" href="https://gnosisscan.io/address/${r.address}" target="_blank" rel="noopener noreferrer"><span class="avatar-glyph" aria-hidden="true">${r.address.slice(2,4).toUpperCase()}</span><span class="mono">${esc(r.username||short(r.address))} ↗</span></a></td><td><button class="score-badge" data-score="${r.address}" aria-label="Trader score details for ${short(r.address)}"><svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="12" fill="none" stroke="var(--nested)" stroke-width="3"/><circle cx="16" cy="16" r="12" fill="none" stroke="var(--violet-text)" stroke-width="3" pathLength="100" stroke-dasharray="${r.score||0} 100" transform="rotate(-90 16 16)"/></svg><span>${r.score==null?'Unscored':num(r.score)}<small class="tier-chip label-shape" title="Trader score tier">${esc(r.tier||'1 scored market')}</small></span></button></td><td class="${r.pnl<0?'negative':'positive'}">${r.pnl<0?'−':'+'}${money(Math.abs(r.pnl))}</td><td>${money(r.volume)}</td><td class="${r.roi<0?'negative':'positive'}">${r.roi<0?'−':'+'}${pct(Math.abs(r.roi)*100)}%</td><td>${r.marketCount}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">'+(available?'No matching accounts':'No captured rows for these filters')+'</td></tr>'}</tbody></table></div><div class="leader-pagination"><button id="leader-prev" class="soft" ${leaders.page===0?'disabled title="First page"':''}>Previous</button><span>Page ${leaders.page+1} of ${pages}</span><button id="leader-next" class="soft" ${leaders.page===pages-1?'disabled title="Last captured page"':''}>Next</button></div>`;
document.querySelectorAll('[data-leader-sort]').forEach(b=>b.onclick=()=>{const k=b.dataset.leaderSort;leaders.desc=leaders.sort===k?!leaders.desc:true;leaders.sort=k;leaders.page=0;leaderTable();});$('#leader-prev').onclick=()=>{leaders.page--;leaderTable();};$('#leader-next').onclick=()=>{leaders.page++;leaderTable();};
document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{const r=d.rows.find(r=>r.address===b.dataset.score);modal('Trader Score',r.scoreBreakdown?`<p>${num(r.score)} · ${esc(r.tier)}</p><div class="detail-list">${Object.entries(r.scoreBreakdown.components).map(([k,v])=>`<div><span>${esc(k)}</span><b>${num(v)}</b></div>`).join('')}</div><p>${r.scoreBreakdown.sampleShrink.scoredMarketCount} scored markets · Sample factor ${pct(r.scoreBreakdown.sampleShrink.factor*100)}%</p>`:`<p>${r.scoreUnavailable.scoredMarketCount} scored market. At least ${r.scoreUnavailable.minScoredMarkets} are required.</p>`);});}


window.addEventListener('resize',()=>{const host=$('#winning-chart');if(!host)return;const m=state.markets.find(m=>location.hash==='#/market/'+m.id);if(m){host.innerHTML=winningChart(m);wireChart(m);}});

(function(){const tip=document.createElement('div');tip.className='chance-tip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);
const set=(i,on)=>{document.querySelectorAll('.chance-dial').forEach(d=>{d.classList.toggle('has-focus',on);d.querySelectorAll('.chance-arc').forEach(a=>a.classList.toggle('is-on',on&&a.dataset.i===String(i)));});document.querySelectorAll('.chance-labels [data-i]').forEach(l=>l.classList.toggle('is-on',on&&l.dataset.i===String(i)));};
const show=(a,x,y)=>{tip.innerHTML='<b>'+a.dataset.name+'</b><span>'+pct(a.dataset.pct)+'% chance</span>';tip.hidden=false;const w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-w-8,x+14))+'px';tip.style.top=Math.max(8,y-h-12)+'px';};
document.addEventListener('pointermove',e=>{const a=e.target.closest?.('.chance-arc');if(a){set(a.dataset.i,true);show(a,e.clientX,e.clientY);return;}const l=e.target.closest?.('.chance-labels [data-i]');if(l){const arc=document.querySelector('.chance-arc[data-i="'+l.dataset.i+'"]');set(l.dataset.i,true);if(arc){const r=arc.getBoundingClientRect();show(arc,r.left+r.width/2,r.top+r.height/2);}return;}if(!tip.hidden){tip.hidden=true;set(0,false);}});
document.addEventListener('focusin',e=>{const t=e.target.closest?.('.chance-arc,.chance-labels [data-i]');if(!t)return;const i=t.dataset.i;const arc=document.querySelector('.chance-arc[data-i="'+i+'"]');set(i,true);if(arc){const r=arc.getBoundingClientRect();show(arc,r.left+r.width/2,r.top+r.height/2);}});
document.addEventListener('focusout',e=>{if(e.target.closest?.('.chance-arc,.chance-labels [data-i]')){tip.hidden=true;set(0,false);}});
addEventListener('hashchange',()=>{tip.hidden=true;});})();

// The source appendix calls this helper but omits its declaration. Geometry follows
// the brief's coin chart measurements; stack height comes only from captured PnL.
function coin(x,y,rx,ry,depth,i,c){return `<g class="coin" style="--i:${i};color:${c}"><ellipse cx="${x}" cy="${y+depth}" rx="${rx}" ry="${ry}" class="coin-side"/><path d="M${x-rx} ${y}v${depth}a${rx} ${ry} 0 0 0 ${rx*2} 0v-${depth}" class="coin-side"/><ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" class="coin-face"/><ellipse cx="${x}" cy="${y}" rx="${rx-4}" ry="${ry-2}" class="coin-etch"/></g>`;}
function leaderVisuals(rows){const top=[...rows].sort((a,b)=>b.pnl-a.pnl).slice(0,10),max=Math.max(1,...top.map(r=>Math.abs(r.pnl)));return `<section class="profit-ranking" aria-label="Top ten traders by profit">${top.map((r,i)=>`<div class="profit-row"><b>${i+1}</b><span class="mono">${short(r.address)}</span><i><i style="transform:scaleX(${Math.abs(r.pnl)/max})"></i></i><strong class="num">${money(r.pnl)} P&amp;L</strong></div>`).join('')}</section>`;}



function normalizeLegacyRoute(){
 const hash=location.hash;
 if(hash.startsWith('#/markets')){const old=new URLSearchParams(hash.split('?')[1]||'');const q=new URLSearchParams();for(const [k,v]of old){const key={marketName:'q',kind:'type',view:'view'}[k]||k;if(key==='view'&&v==='index')q.set(key,'table');else if(key==='type'&&v==='Multi-categorical')q.set(key,'Categorical');else if(key==='type'&&v==='Multi-scalar')q.set(key,'Multi-outcome');else q.set(key,v);}history.replaceState(null,'','#/?'+q);}
 const value=decodeURIComponent((location.hash.match(/^#\/market\/(.+?)(?:\?|$)/)||[])[1]||'');
 if(value&&!state.markets.some(m=>m.id===value)){const slug=value.split('/').pop(),m=state.markets.find(m=>m.url===slug||m.id===slug);if(m)history.replaceState(null,'','#/market/'+m.id);}
}

// Shared captured-data preparation, exercised by command-deck.mjs.
function prepareMarkets(data){const byId=new Map();data.markets.forEach(m=>{if(!byId.has(m.id))byId.set(m.id,m);});state.markets=[...byId.values()];const names=new Map();[...state.markets].sort((a,b)=>Number(!!conditional(a))-Number(!!conditional(b))).forEach(m=>{const key=m.marketName.trim().toLowerCase().replace(/\s+/g,' ');if(!names.has(key))names.set(key,m);});state.listMarkets=[...names.values()].filter(m=>Number(m.volumeUSD)>0&&outcomes(m).length>0&&m.outcomes.every((n,i)=>n.trim().toLowerCase()==='invalid'||Number.isFinite(m.odds?.[i])));}

// Keep keyboard focus within the mobile overlays; native dialogs manage their own focus.
document.addEventListener('keydown',e=>{
 if(dialog.open||e.key!=='Tab')return;
 const panel=!desktop()?document.querySelector('#ix-panel.open'):null;
 const consolePanel=innerWidth<=1050?document.querySelector('.trade.open'):null;
 const overlay=panel||consolePanel;if(!overlay)return;
 const items=[...overlay.querySelectorAll('a[href],button,input,select,summary,[tabindex="0"]')].filter(el=>!el.disabled&&!el.closest('[inert]')&&el.getClientRects().length);
 if(!items.length)return;const i=items.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&(i===items.length-1||i<0)){e.preventDefault();items[0].focus();}
});

function toggleConsole(open){const el=$('.trade');if(!el)return;el.classList.toggle('open',open);$('#mobile-trade')?.setAttribute('aria-expanded',String(open));if(innerWidth<=1050){if(open){el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');}else{el.removeAttribute('role');el.removeAttribute('aria-modal');}document.body.classList.toggle('console-open',open);(open?$('.trade-close'):$('#mobile-trade'))?.focus({preventScroll:true});}}

function hIcon(name){return `<svg class="ui-icon" viewBox="0 0 20 20" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#h-${name}"/></svg>`;}

function hMark(m){const o=outcomes(m)[0];return o?`<div class="tile-mark"><strong class="num">${pct(o.p)}<small>%</small></strong><span class="prob-track"><i style="transform:scaleX(${clamp(o.p)/100})"></i></span></div>`:'';}

function hQuickError(a,buy=true){if(!Number.isFinite(a)||a<=0)return 'Enter an amount greater than zero.';if(a<1)return 'Minimum amount is 1.';if(a>10000)return 'Maximum amount is 10,000.';if(buy&&a>wallet.balance)return `Exceeds demo balance of ${num(wallet.balance)}.`;return '';}

function hWireQuickAmount(m){const input=$('#quick-amount');if(!input)return;input.addEventListener('input',()=>{const value=input.value,focused=document.activeElement===input,scroll=$('.pn-scroll')?.scrollTop||0;state.tAmt=Number(value)||0;panel();const next=$('#quick-amount');next.value=value;$('.pn-scroll').scrollTop=scroll;if(focused)next.focus({preventScroll:true});});}

function hSyncPanels(){
 cancelAnimationFrame(window.hPanelFrame||0);window.hPanelFrame=requestAnimationFrame(()=>{
  for(const panel of document.querySelectorAll('#ix-panel,.trade')){
   const r=panel.getBoundingClientRect(),offset=innerWidth>=1100?Math.max(128,r.top):innerWidth>1050&&panel.matches('.trade')?Math.max(128,r.top):80;
   panel.style.setProperty('--panel-offset',offset+'px');
   const scroller=panel.querySelector('.pn-scroll,.trade-body');if(!scroller)continue;
   const update=()=>{panel.classList.toggle('can-scroll-up',scroller.scrollTop>2);panel.classList.toggle('can-scroll-down',scroller.scrollTop+scroller.clientHeight<scroller.scrollHeight-2);};
   scroller.onscroll=update;update();
  }
 });
}

function hSyntax(root=document){for(const pre of root.querySelectorAll('pre')){const text=pre.textContent;if(!/^[\s\n]*[\{\[]/.test(text))continue;pre.innerHTML=h(text).replace(/(&quot;[^\n]*?&quot;)(\s*:)?|\b(true|false|null)\b|\b(-?\d+(?:\.\d+)?)\b/g,(match,str,key,word,n)=>str?`<span class="json-${key?'key':'string'}">${str}</span>${key||''}`:`<span class="json-${word?'literal':'number'}">${word||n}</span>`);}}

function hSegment(root=document){for(const el of root.querySelectorAll('.seg,.mode,.period-tabs,.pn-ranges,.ranges,.tabs')){const items=[...el.querySelectorAll(':scope > button')],active=items.find(x=>x.getAttribute('aria-pressed')==='true'||x.classList.contains('active'));if(!active)continue;const r=active.getBoundingClientRect(),p=el.getBoundingClientRect();el.style.setProperty('--thumb-x',(r.left-p.left)+'px');el.style.setProperty('--thumb-w',r.width+'px');}}

function hHistoryCrosshair(m){
 const host=$('.history-canvas'),data=chartData(m);if(!host||!data)return;const points=data.groups[0]?.points||[];if(!points.length)return;let index=points.length-1;
 const draw=i=>{index=Math.max(0,Math.min(points.length-1,i));const p=points[index],x=42+(p.t-data.start)/Math.max(1,data.end-data.start)*504,y=176-p.p*1.52,g=$('.history-crosshair',host);if(!g)return;g.hidden=false;g.removeAttribute('hidden');const line=$('path',g);line.setAttribute('d',`M${x} 24V176`);$('circle',g).setAttribute('cx',x);$('circle',g).setAttribute('cy',y);const left=Math.max(44,Math.min(350,x-96));$('rect',g).setAttribute('x',left);$('rect',g).setAttribute('y','24');const label=$('text',g);label.setAttribute('x',left+10);label.setAttribute('y','48');label.textContent=`${pct(p.p)}% · ${date(p.t)}`;host.setAttribute('aria-label',`${data.groups[0].name}, ${pct(p.p)} percent on ${date(p.t)}. Use arrows to read observations.`);};
 host.onpointermove=e=>{const r=host.getBoundingClientRect(),t=data.start+Math.max(0,Math.min(1,((e.clientX-r.left)/r.width*620-42)/504))*(data.end-data.start);let best=0;points.forEach((p,i)=>{if(Math.abs(p.t-t)<Math.abs(points[best].t-t))best=i;});draw(best);};
 host.onpointerleave=()=>$('.history-crosshair',host)?.setAttribute('hidden','');host.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();draw(e.key==='Home'?0:e.key==='End'?points.length-1:index+(e.key==='ArrowRight'?1:-1));}};
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-open-trade]');if(b){e.stopPropagation();location.hash='#/market/'+b.dataset.openTrade;return;}const c=e.target.closest('[data-copy-asker],[data-copy-value]');if(c){e.stopPropagation();copy(c.dataset.copyAsker||c.dataset.copyValue);}},true);
window.addEventListener('scroll',hSyncPanels,{passive:true});window.addEventListener('resize',()=>{hSyncPanels();hSegment();});
new MutationObserver(()=>{hSyntax();hSegment();hSyncPanels();hUpgradeIcons();hEnhanceSupporting();}).observe(document.querySelector('#app'),{childList:true,subtree:false});

function hUpgradeIcons(root=document){for(const button of root.querySelectorAll('button,a')){if(button.closest('pre')||button.matches('.asker-link,.copy-asker'))continue;const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('svg,pre')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){let text=node.textContent;const glyph=text.trim().match(/^[×?✓]$|[↗⌄↑↓◇←]/);if(!glyph)continue;let icon={"×":"close","?":"help","✓":"check","↗":"arrow","⌄":"chevron","↑":"arrow","↓":"sort","◇":"chain","←":"back"}[glyph[0]];if(!icon)continue;node.textContent=text.replace(glyph[0],'').trim();const span=document.createElement('span');span.innerHTML=hIcon(icon);node.parentElement.append(span.firstElementChild);}}}

function hRollQuick(){document.querySelectorAll('.quote-num').forEach(el=>rollTo(el,el.textContent));}
function hEnhanceSupporting(){const details=document.querySelector('.score-explainer');if(details&&!details.querySelector('.score-popover')){const body=document.createElement('div');body.className='score-popover';body.setAttribute('role','region');body.setAttribute('aria-label','How the Trader Score works');for(const child of [...details.children])if(child.tagName!=='SUMMARY')body.append(child);details.append(body);details.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();details.open=false;details.querySelector('summary').focus();}});}const heading=document.querySelector('.create-heading .eyebrow');if(heading)heading.classList.add('step-caption');}
document.addEventListener('pointerdown',e=>{const d=document.querySelector('.score-explainer[open]');if(d&&!d.contains(e.target))d.open=false;});

function tradeQuote(m){const o=outcomes(m).find(v=>v.i===(state.tOut??state.selected))||outcomes(m)[0],p=Math.max(.001,Math.min(.999,(o?.p||0)/100)),a=Number.isFinite(Number(state.tAmt))?Math.max(0,Number(state.tAmt)):0,L=Number.isFinite(Number(m.liquidityUSD))?Math.max(1,Number(m.liquidityUSD)):1,sell=state.side==='sell',reserve=L/(2*p),delta=sell?a:a/p,after=Math.max(.001,Math.min(.999,p*(reserve/(sell?reserve+delta:Math.max(reserve*.001,reserve-delta)))**2)),avg=(p+after)/2,get=sell?a*avg:a/avg;return {m,name:o?.name||'Outcome',sell,pay:a,get,avg,after,impact:Math.abs(after-p)*100};}
function tradeHead(m){return `<div class="ticket-navigation"><button type="button" class="back-markets" data-ticket-back>${hIcon('back')}Back to markets</button><a class="ticket-open soft" id="pn-open" href="#/market/${m.id}" aria-label="Open full market page" title="Open full market page">${hIcon('arrow')}</a><button type="button" class="ticket-close" data-ticket-back aria-label="Close trade">${hIcon('close')}</button></div><div class="ticket-heading">${mkImg(m,'ticket-photo',true)}<div><h3 title="${h(m.marketName)}">${h(m.marketName)}</h3><p>Asked by <span class="mono">${h(askerLabel(m.creator))}</span></p></div></div>`;}
function unifiedTicket(m,full=false){const os=outcomes(m),q=tradeQuote(m),id=full?'amount':'quick-amount';return `<section class="unified-ticket pn-trade" aria-label="Trade ticket" data-market="${m.id}">${tradeHead(m)}<div class="seg tk-side" aria-label="Buy or sell">${['buy','sell'].map(v=>`<button data-side2="${v}" aria-pressed="${state.side===v}">${v==='buy'?'Buy':'Sell'}</button>`).join('')}</div><div class="outcome-cards">${os.slice(0,4).map(o=>`<button data-out="${o.i}" aria-pressed="${o.name===q.name}"><span>${h(o.name)}</span><strong class="num">${(o.p/100).toFixed(2)}</strong><small>${pct(o.p)}% chance</small><i class="prob-track"><i style="transform:scaleX(${clamp(o.p)/100})"></i></i></button>`).join('')}</div>${os.length>4?`<label class="more-outcomes">More outcomes<select data-more-outcome aria-label="More outcomes"><option value="">Choose outcome</option>${os.slice(4).map(o=>`<option value="${o.i}" ${o.name===q.name?'selected':''}>${h(o.name)} · ${pct(o.p)}%</option>`).join('')}</select></label>`:''}<label class="ticket-amount" for="${id}"><span data-amount-label>${q.sell?'Shares to sell':'You pay'}</span><input id="${id}" type="number" min="1" max="1000" step="1" value="${state.tAmt}" inputmode="decimal" aria-describedby="quick-err"></label><input type="range" id="amount-slider" min="1" max="1000" step="1" value="${state.tAmt}" aria-label="Order amount"><div class="tk-chips">${[10,50,100,500,'Max'].map(v=>`<button data-amt="${v==='Max'?Math.min(1000,wallet.balance):v}">${v}</button>`).join('')}</div><p class="field-error" id="quick-err" role="status"></p><dl class="ticket-metrics" aria-live="polite"></dl><p class="what-happens">${scalar(m)?'Payout settles proportionally within the market range.':`Pays 1 per share if <b data-payoff-name>${h(q.name)}</b> wins`}</p>${full?'':`<div class="ticket-action"><button class="primary" id="tk-connect">Preview order</button></div>`}</section>`;}
function wireUnified(root,m,full=false){const ticket=$('.unified-ticket',root);if(!ticket)return;const input=$('input[type=number]',ticket),slider=$('input[type=range]',ticket),go=full?$('#tr-go'):$('#tk-connect',root);const update=()=>{const q=tradeQuote(m);state.q=q;state.amount=q.pay;state.selected=state.tOut??outcomes(m)[0]?.i;input.value=state.tAmt;slider.value=state.tAmt;const err=(!Number.isFinite(state.tAmt)||state.tAmt<1?'Enter an amount from 1 to 1,000.':'')||hQuickError(q.pay,!q.sell)||(q.pay>1000?'Maximum amount is 1,000.':'');$('#quick-err',ticket).textContent=err;input.setAttribute('aria-invalid',String(!!err));$('[data-amount-label]',ticket).textContent=q.sell?'Shares to sell':'You pay';ticket.querySelectorAll('[data-out]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.out)===state.selected)));ticket.querySelectorAll('[data-side2]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.side2===state.side)));const payoff=$('[data-payoff-name]',ticket);if(payoff)payoff.textContent=q.name;const rows=[['You pay',q.sell?0:q.pay],['Shares',q.sell?0:q.get],['Avg price',q.avg.toFixed(2)],['Price impact',pct(q.impact)+'%'],[q.sell?'You receive':'Payout',q.get],['New chance',pct(q.after*100)+'%']];$('.ticket-metrics',ticket).innerHTML=rows.map(([label,value])=>`<div><dt>${label}</dt><dd class="num quote-num">${typeof value==='number'?num(value):value}</dd></div>`).join('');go.disabled=!!err;go.textContent=connected()?'Preview order':'Connect wallet';hSegment(ticket);ticketSelection(ticket);hRollQuick();};input.oninput=()=>{state.tAmt=Number(input.value)||0;const raw=input.value;update();input.value=raw;};slider.oninput=()=>{state.tAmt=Number(slider.value);update();};ticket.querySelectorAll('[data-amt]').forEach(b=>b.onclick=()=>{state.tAmt=Number(b.dataset.amt);update();});ticket.querySelectorAll('[data-side2]').forEach(b=>b.onclick=()=>{state.side=b.dataset.side2;update();});ticket.querySelectorAll('[data-out]').forEach(b=>b.onclick=()=>{state.tOut=Number(b.dataset.out);update();});$('[data-more-outcome]',ticket)?.addEventListener('change',e=>{if(e.target.value!==''){state.tOut=Number(e.target.value);update();}});ticket.querySelectorAll('[data-ticket-back]').forEach(b=>b.onclick=backMarkets);go.onclick=()=>{if(!connected()){connect();return;}confirmTrade(tradeQuote(m));};update();}
function setCta(){const b=$('#tr-go')||$('#tk-connect');if(b)b.textContent=connected()?'Preview order':'Connect wallet';}
function backMarkets(){if(dialog.open)dialog.close();if(isHome()){closeSheet();document.querySelector('.ix-main')?.scrollIntoView({block:'start',behavior:reduced()?'instant':'smooth'});$('.ix-main')?.focus({preventScroll:true});}else location.hash='#/';}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open&&!state.details&&route().startsWith('#/market/'))backMarkets();});

// Slide one inset selection ring without replacing the outcome buttons.
function ticketSelection(ticket){
 const cards=$('.outcome-cards',ticket),active=$('[data-out][aria-pressed=true]',cards);
 if(!active){cards.classList.remove('has-selection');return;}
 cards.classList.add('has-selection');
 cards.style.setProperty('--selection-x',active.offsetLeft+'px');
 cards.style.setProperty('--selection-width',active.offsetWidth+'px');
}

function easeTicketAmount(ticket,value){
 const el=$('.ticket-amount-display',ticket);if(!el)return;
 cancelAnimationFrame(el.amountFrame);
 const from=Number(el.dataset.amount??el.textContent),start=performance.now();
 if(reduced()||from===value){el.textContent=value;el.dataset.amount=value;return;}
 const tick=now=>{const t=Math.min(1,(now-start)/280),n=from+(value-from)*(1-Math.pow(1-t,3));el.dataset.amount=n;el.textContent=t===1?value:Math.round(n);if(t<1&&el.isConnected)el.amountFrame=requestAnimationFrame(tick);};
 el.amountFrame=requestAnimationFrame(tick);
}

window.addEventListener('resize',()=>document.querySelectorAll('.unified-ticket').forEach(ticketSelection));
